O = {
"c337:xt53_1_48": ("범위를 **조절해 점진적으로** 늘림", "**다이얼 락**은 굽힘·폄 각도를 조금씩 바꿔 고정할 수 있어 구축 범위를 점진적으로 늘리는 데 써요.", "'링 락'으로 바꾸면 틀려요. 링 락은 완전 폄 고정이에요.", "단계 조절 = 다이얼 락", 3),
"c337:xo53_2_53": ("**짧은**맞섬보조기의 범위", "짧은맞섬보조기는 **손만** 받쳐요. 손목까지 고정하는 것은 긴맞섬보조기예요.", "짧은맞섬보조기는 **손목을 포함하지 않는다**(손목까지는 긴맞섬보조기).", "짧은 건 손만, 긴 건 손목까지", 3),
"c337:xt53_2_53": ("손목까지 고정하는 맞섬보조기", "정중신경 손상으로 손목도 약하면 손목을 20° 정도 펴서 고정하는 **긴맞섬보조기**를 써요.", "'짧은맞섬보조기'로 바꾸면 틀려요.", "손목까지면 긴맞섬", 3),
"c337:xo51_2_53": ("**발등굽힘근 약화** 보조기", "발등굽힘근 약화에는 스프링으로 발을 들어 주는 **클렌작(발등굽힘 보조) 발목관절**을 써요. 고정형만 쓰는 것은 아니에요.", "발등굽힘근 약화에는 **클렌작(발등굽힘 보조) 발목관절**을 쓴다.", "발처짐엔 클렌작(스프링)", 4),
"c337:xt51_2_53": ("발등굽힘근 약화 **발목관절**", "깊은종아리신경 손상 등 발등굽힘근이 약하면 스프링이 발을 들어 주는 **클렌작 발목관절**을 써요.", "'고정형 발목관절'로 바꾸면 틀려요.", "발처짐 = 클렌작", 4),
"c338:xo52_1_48": ("**윌리엄 보조기**가 막는 움직임", "윌리엄 보조기는 허리 **폄과 가쪽굽힘을 막고 굽힘은 허용**해요. 허리앞굽음을 줄이는 목적이에요.", "윌리엄 보조기는 허리 **굽힘을 허용**하고 폄·가쪽굽힘을 막는다.", "윌리엄은 굽힘 허용", 4),
"c338:xo51_1_48": ("**필라델피아** 보조기의 제한", "필라델피아 칼라는 목 **굽힘·폄**을 주로 막고 돌림 제한은 약해요. 굽힘·돌림까지 더 잘 막는 것은 SOMI 같은 목가슴 보조기예요.", "필라델피아 보조기는 목 **굽힘·폄**을 주로 제한한다(돌림 제한은 약함).", "필라델피아는 굽폄, 돌림은 약하다", 3),
"c338:xo50_1_48": ("**모든 방향**을 최대로 막는 보조기", "척추 모든 방향을 가장 강하게 막는 것은 **플라스틱 몸통재킷**이에요. 나이트-테일러는 굽힘·폄 위주로 제한해요.", "**플라스틱 몸통재킷**은 척추 모든 방향의 운동을 최대한 막는다.", "전 방향 최대 = 몸통재킷", 3),
"c338:xo50_2_28": ("**압박골절** 과다폄 보조기", "과다폄을 유지해 압박골절에 쓰는 것은 **쥬엣 보조기**예요. 윌리엄 보조기는 허리 굽힘을 허용하는 보조기예요.", "**쥬엣 보조기**는 과다폄을 유지해 압박골절에 쓴다.", "압박골절 = 쥬엣", 4),
"c339:xo52_2_27": ("**파블릭** 보조기의 적응증", "파블릭 보장구는 영아의 **발달성 엉덩관절 이형성증**에 써요. 레그-칼베-페르테스병에는 토론토 같은 벌림 보조기를 써요.", "파블릭 보조기는 **발달성 엉덩관절 이형성증**에 쓴다.", "이형성증은 파블릭, 페르테스는 토론토", 4),
"c339:xt52_2_27": ("**넙다리뼈머리 무혈괴사** 소아", "레그-칼베-페르테스병은 넙다리뼈머리를 절구에 담아 두려고 **토론토 보조기**로 벌림·안쪽돌림을 유지해요.", "'파블릭 보조기'로 바꾸면 틀려요.", "페르테스 = 토론토(벌림 + 안쪽돌림)", 3),
"c340:xo52_1_49": ("매우 짧은 잘린끝 **2:1** 장치", "매우 짧은 아래팔 잘린끝에 2:1 비율 팔꿉 장치를 쓰는 것은 **분리형(스플릿) 소켓**이에요. 흡착식 소켓은 넙다리 절단에서 공기압으로 의지를 붙이는 소켓이에요.", "**분리형(스플릿) 소켓**은 매우 짧은 잘린끝에 쓰는 2:1 장치다.", "매우 짧은 아래팔 = 분리형(2배 증폭)", 3),
"c340:xt52_1_49": ("2:1 비율 팔꿉 장치", "잘린끝이 30° 굽혀지면 의지는 60° 굽혀지도록 움직임을 키우는 것이 **분리형(스플릿) 소켓 + 증폭 힌지**예요.", "'뮌스터 소켓'으로 바꾸면 틀려요. 뮌스터는 짧은 아래팔용이에요.", "아주 짧으면 분리형", 3),
"c340:xo51_1_49": ("**PTB** 소켓의 체중지지", "PTB 소켓은 **무릎뼈힘줄(무릎인대)** 로 체중을 지지해요. 잘린끝으로 체중을 지지하는 것은 사임 소켓이에요.", "PTB 소켓은 **무릎뼈힘줄**로 체중을 지지한다.", "PTB = 무릎뼈힘줄, 사임 = 잘린끝", 4),
"c340:xt51_1_49": ("잘린끝 **체중지지** 소켓", "발목 바로 위 절단은 잘린끝으로 체중을 받칠 수 있어 **사임(Syme) 소켓**을 써요.", "'PTB 소켓'으로 바꾸면 틀려요.", "발목 위 = 사임", 3),
"c340:xo50_1_49": ("**네모공간 소켓**의 절단 부위", "네모공간(사각) 소켓은 **넙다리(무릎 위) 절단**용으로, 궁둥뼈결절로 체중을 받쳐요.", "네모공간 소켓은 **넙다리(무릎 위) 절단**용 소켓이다.", "사각 소켓 = 넙다리, 궁둥뼈결절", 3),
"c340:xt50_1_49": ("짧은 아래팔 절단 **팔꿉 감싸기**", "짧은 아래팔 절단에서 팔꿈치머리와 위관절융기를 감싸 빠지지 않게 하는 것이 **뮌스터 소켓**이에요.", "'네모공간 소켓'으로 바꾸면 틀려요.", "짧은 아래팔 = 뮌스터", 3),
"c342:xo53_1_50": ("지팡이 **손잡이 높이**", "지팡이 손잡이는 **넙다리뼈 큰돌기** 높이에 맞춰요. 그러면 팔꿉이 20~30° 굽혀져요.", "지팡이 손잡이는 **큰돌기** 높이에 맞춘다.", "손잡이는 큰돌기", 5),
"c342:xo52_1_50": ("**보행기**와 계단", "보행기는 평지에서 가장 안정적이지만 들고 옮겨야 해서 **계단에서는 쓰기 어려워요**.", "보행기는 계단에서 **쓰기 어렵다**.", "평지는 보행기, 계단은 어렵다", 4),
"c342:xo51_1_50": ("**위팔세갈래근 약화** 보조기구", "위팔세갈래근이 약하면 위팔을 받쳐 팔꿉 폄을 돕는 **캐나디안(위팔세갈래근) 크러치**를 써요.", "위팔세갈래근이 약하면 **캐나디안 크러치**를 쓴다.", "세갈래근 약화 = 캐나디안", 3),
"c342:xo50_1_50": ("**팔꿉 굽힘구축** 환자 목발", "팔꿉이 펴지지 않으면 아래팔로 체중을 싣는 **플랫폼 목발**이 알맞아요.", "팔꿉 굽힘구축 환자에게는 **플랫폼 목발**이 가장 알맞다.", "팔꿉·손목 문제 = 플랫폼", 3),
}
